trait Observer {
    fn update(&self, value: i32);
}

struct Subject {
    observers: Vec<Box<dyn Observer>>,
    state: i32,
}

impl Subject {
    fn new() -> Self { Subject { observers: vec![], state: 0 } }
    fn attach(&mut self, obs: Box<dyn Observer>) { self.observers.push(obs); }
    fn set_state(&mut self, val: i32) {
        self.state = val;
        for obs in &self.observers { obs.update(val); }
    }
}

class EventEmitter:
    def __init__(self):
        self._listeners = {}
    def on(self, event, fn):
        self._listeners.setdefault(event, []).append(fn)
    def emit(self, event, *args):
        for fn in self._listeners.get(event, []):
            fn(*args)

from abc import ABC, abstractmethod

class Transport(ABC):
    @abstractmethod
    def deliver(self): pass

class Truck(Transport):
    def deliver(self): return 'Deliver by road'

class Ship(Transport):
    def deliver(self): return 'Deliver by sea'

def create_transport(mode):
    if mode == 'road': return Truck()
    if mode == 'sea': return Ship()
    raise ValueError(f'Unknown mode: {mode}')

trait Shape {
    fn area(&self) -> f64;
}
struct Circle { radius: f64 }
impl Shape for Circle {
    fn area(&self) -> f64 { std::f64::consts::PI * self.radius * self.radius }
}
struct Square { side: f64 }
impl Shape for Square {
    fn area(&self) -> f64 { self.side * self.side }
}
fn create_shape(kind: &str, size: f64) -> Box<dyn Shape> {
    match kind {
        "circle" => Box::new(Circle { radius: size }),
        "square" => Box::new(Square { side: size }),
        _ => panic!("unknown shape"),
    }
}

trait SortStrategy {
    fn sort(&self, data: &mut Vec<i32>);
}
struct BubbleSort;
impl SortStrategy for BubbleSort {
    fn sort(&self, data: &mut Vec<i32>) {
        let n = data.len();
        for i in 0..n { for j in 0..n-i-1 { if data[j] > data[j+1] { data.swap(j, j+1); } } }
    }
}

